<script setup lang="ts">
import {ref,watch,onMounted,computed} from 'vue';import {api} from '../api';import Modal from './Modal.vue';import type {WorkTab} from '../stores';
const props=defineProps<{record:any;tab:WorkTab}>(),emit=defineEmits<{cancel:[];saved:[]}>(),data=ref<any>(null),date=ref(''),reason=ref(''),review=ref(false),loading=ref(false),error=ref('');let requestId='',key='';
watch([date,reason],()=>review.value=false);
const changes=computed(()=>{if(!data.value||!/^\d{4}-\d{2}-\d{2}$/.test(date.value))return [];const [y,m,d]=date.value.split('-').map(Number),total=new Date(Date.UTC(y,m,0)).getUTCDate();return data.value.months.map((r:any)=>({...r,newDays:r.store_id===props.record.from_store_id?d-1:total-d+1}));});
async function load(){loading.value=true;error.value='';review.value=false;try{data.value=await api('transfers/correct?id='+props.record.id);if(!date.value)date.value=data.value.row.effective_date;}catch(e){error.value=(e as Error).message;data.value=null;}finally{loading.value=false;}}
function inspect(){error.value='';if(date.value===data.value.row.effective_date){error.value='新日期與原日期相同';return;}if(date.value.slice(0,7)!==data.value.row.effective_date.slice(0,7)){error.value='目前僅開放同月份更正；跨月人工核對與提交流程建置中';return;}if(!reason.value.trim()){error.value='請填寫更正原因';return;}review.value=true;}
async function save(){if(!review.value||props.tab.busy)return;props.tab.busy=true;error.value='';const payload={id:props.record.id,effective_date:date.value,reason:reason.value.trim(),version:data.value.version},next=JSON.stringify(payload);if(next!==key){key=next;requestId=crypto.randomUUID();}try{await api('transfers/correct',{method:'POST',body:JSON.stringify({...payload,requestId})});emit('saved');}catch(e){error.value=(e as Error).message;review.value=false;}finally{props.tab.busy=false;}}
function close(){if(!props.tab.busy&&!loading.value)emit('cancel');}onMounted(load);
</script>
<template><Modal title="更正調店生效日期" @cancel="close"><p><strong>{{record.employee_code}} {{record.employee_name}}</strong></p><p>{{record.from_store?.store_name}} → {{record.to_store?.store_name}}</p><p v-if="loading" role="status">正在載入…</p><p v-if="error" role="alert" class="notice error">{{error}}</p><template v-if="data"><p>原生效日：{{data.row.effective_date}}。目前僅開放同月份、非未來日期的更正。</p><form @submit.prevent="inspect"><fieldset :disabled="loading||tab.busy"><label>新生效日期<input v-model="date" type="date" required min="2000-01-01" max="2100-12-31"></label><label>更正原因<textarea v-model="reason" required maxlength="2000" rows="3"></textarea></label><button type="submit">核對更正內容</button></fieldset></form><template v-if="review"><p>{{data.row.effective_date}} → {{date}}</p><div v-if="changes.length" class="module-table"><table><thead><tr><th>門市</th><th>原天數</th><th>更正後</th></tr></thead><tbody><tr v-for="r in changes" :key="r.id"><td>{{r.store_id===record.from_store_id?'調出門市':'調入門市'}}</td><td>{{r.work_days}}</td><td>{{r.newDays}}</td></tr></tbody></table></div><p v-else>當月尚無需要調整的人員月資料。</p><p>一併更新異動與主檔的調店日期，保留其他手填內容。</p></template></template><div class="dialog-actions"><button :disabled="loading||tab.busy" @click="close">返回</button><button :disabled="loading||tab.busy" @click="load">重新載入</button><button v-if="review" class="primary" :disabled="tab.busy" @click="save">{{tab.busy?'正在更正…':'確認更正'}}</button></div></Modal></template>
<style scoped>fieldset{border:0;padding:0;display:grid;gap:16px;min-width:0}label{display:grid;gap:8px}input,textarea{width:100%;min-width:0}.module-table table{min-width:0;width:100%}.module-table th,.module-table td{padding:10px 8px}</style>
